<template>
  <div class="row">
    <q-badge
      v-for="(value, key) in filterValue"
      :key="value"
      color="primary"
      rounded
      class="text-capitalize cursor-pointer q-ml-xs"
    >
      <template v-slot>
        {{ $t(value) }}
        <div>
          <q-icon
            name="close"
            color="white"
            size="xs"
            class="q-ml-xs cursor-pointer"
            style="font-size: 12px !important"
            @click="removeFilter(key)"
          />
        </div>
      </template>
    </q-badge>
  </div>
</template>
<script lang="ts">
import { storeToRefs } from 'pinia';
import { useColumnFilterStore } from 'src/store/main';
import { defineComponent, ref } from 'vue';
import { dynamicObj } from '../assets';
export default defineComponent({
  mixins: [],
  props: {
    name: {
      type: String,
      required: true,
      hint: 'Name of the filter',
    },
  },
  components: {},
  computed: {
    filterValue() {
      const filterObj = this.quickFilterMap.get(this.name);
      if (filterObj) {
        return filterObj as dynamicObj;
      } else {
        return {};
      }
    },
  },

  mounted: function () {
    document.addEventListener('remove_filter_key', this.removeFilterEvent);
  },
  unmounted: function () {
    document.removeEventListener('remove_filter_key', this.removeFilterEvent);
  },
  methods: {
    removeFilterEvent(e: any) {
      const key = e.detail;
      if (!key) {
        return;
      }
      this.removeFilter(key);
    },
    removeFilter(key: string | number) {
      const filterObj = this.quickFilterMap.get(this.name);
      delete filterObj[key];
      this.quickFilterMap.set(this.name, filterObj);
      this.$emit('onUpdateValue', filterObj);
    },
  },
  setup() {
    const columnFilterStore = useColumnFilterStore();
    const { quickFilterMap } = storeToRefs(columnFilterStore);
    const { resetFilters } = columnFilterStore;
    return {
      quickFilterMap,
      resetFilters,
    };
  },
});
</script>
<style></style>
